package com.example.commerce.payment; import javax.validation.Valid; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/payments")public class PaymentController{private final PaymentService service;public PaymentController(PaymentService s){service=s;}@PostMapping @PreAuthorize("hasRole('CUSTOMER')")ResponseEntity<PaymentDtos.Response> create(@Valid @RequestBody PaymentDtos.Request r){return ResponseEntity.status(201).body(service.create(r));}@GetMapping("/{id}")PaymentDtos.Response one(@PathVariable Long id){return service.one(id);}@PostMapping("/webhooks/mock")@PreAuthorize("hasRole('ADMIN')")PaymentDtos.Response hook(@Valid @RequestBody PaymentDtos.Webhook r){return service.webhook(r);}}
